using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Recovers the 2-step verification password with a password recovery code sent to an email address that was previously set up. Works only when the current authorization state is authorizationStateWaitPassword
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> RecoverAuthenticationPasswordAsync(string recoveryCode = default, string newPassword = default, string newHint = default)
    {

           using var activity =  StartCallActivity("RecoverAuthenticationPasswordAsync", typeof(RecoverAuthenticationPassword).FullName ?? "RecoverAuthenticationPasswordAsync");

           try
           {
             return client.RecoverAuthenticationPasswordAsync(recoveryCode, newPassword, newHint);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
